import React from 'react';
import { SearchResult } from '../services/api';

interface SearchResultsProps {
  results: SearchResult[];
  loading?: boolean;
  error?: string | null;
}

const SearchResults: React.FC<SearchResultsProps> = ({ 
  results, 
  loading = false, 
  error = null 
}) => {
  if (loading) {
    return (
      <div className="search-loading">
        <div className="loading-spinner"></div>
        <p>Searching database...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="search-error">
        <h3>Error</h3>
        <p>{error}</p>
      </div>
    );
  }

  if (results.length === 0) {
    return (
      <div className="no-results">
        <p>No results found. Try a different search term.</p>
      </div>
    );
  }

  return (
    <div className="search-results">
      <h2>Search Results ({results.length})</h2>
      <div className="results-list">
        {results.map((result) => (
          <div key={result.datasetId} className="result-item">
            <h3 className="result-title">{result.name}</h3>
            {result.description && (
              <div className="result-description">
                <p>{result.description}</p>
              </div>
            )}
            {result.content && (
              <div 
                className="result-content"
                dangerouslySetInnerHTML={{ 
                  __html: typeof result.content === 'string' ? result.content : JSON.stringify(result.content, null, 2) 
                }}
              />
            )}
            <div className="result-metadata">
              <strong>ID:</strong> {result.datasetId}
            </div>
            {Object.keys(result).map((key) => {
              if (key !== 'datasetId' && key !== 'name' && key !== 'description' && key !== 'content') {
                return (
                  <div key={key} className="result-metadata">
                    <strong>{key}:</strong> {String(result[key])}
                  </div>
                );
              }
              return null;
            })}
          </div>
        ))}
      </div>
    </div>
  );
};

export default SearchResults;
